function lend(
    uint8 p,
    address u,
    uint256 m,
    uint256 a,
    uint256 r,
    uint256 d,
    address t,
    address x
) public unpaused(p) returns (uint256) {

    // Instantiate market and tokens
    address principal = IMarketPlace(marketPlace).markets(u, m, p);
    if (ITempus(principal).yieldBearingToken() != IERC20Metadata(u)) {
        revert NotEqual('underlying');
    } else if (ITempus(principal).maturityTime() > m) {
        revert NotEqual('maturity');
    }

    // Get the underlying token
    IERC20 underlyingToken = IERC20(u);

    // Transfer funds from user to Illuminate, Scope to avoid stack limit
    Safe.transferFrom(underlyingToken, msg.sender, address(this), a);

    // Add the accumulated fees to the total
    uint256 fee = calculateFee(a);
    fees[u] += fee;

    // Swap on the Tempus Router using the provided market and params
    IERC5095 illuminateToken = IERC5095(principalToken(u, m));
    uint256 returned = ITempus(tempusAddr).depositAndFix(Any(x), Any(t), a - fee, true, r, d) -
        illuminateToken.balanceOf(address(this));

    // Mint Illuminate zero coupons
    illuminateToken.mint(msg.sender, returned);

    emit Lend(p, u, m, returned);
    return returned;
}

function depositAndFix(
    ITempusAMM tempusAMM,
    ITempusPool tempusPool,
    ERC20PermitSignature[] calldata erc20Permits,
    uint256 tokenAmount,
    bool isBackingToken,
    uint256 minTYSRate,
    uint256 deadline,
    address referral
) external payable override nonReentrant returns (uint256, uint256) {
    requireRegistered(address(tempusAMM));
    requireRegistered(address(tempusPool));

    erc20Permits.applyPermits(msg.sender, address(this));

    IPoolShare principalShares = tempusPool.principalShare();
    IPoolShare yieldShares = tempusPool.yieldShare();

    uint256 swapAmount = _deposit(tempusPool, tokenAmount, isBackingToken, referral);
    uint256 minReturn = swapAmount.mulfV(minTYSRate, tempusPool.backingTokenONE());
    swap(tempusAMM, swapAmount, yieldShares, minReturn, deadline);

    // At this point all TYS must be swapped for TPS
    uint256 principalsBalance = principalShares.balanceOf(address(this));
    assert(principalsBalance > 0);

    principalShares.transfer(msg.sender, principalsBalance);
    return (swapAmount, principalsBalance);
}

