function lend(
    uint8 p,
    address u,
    uint256 m,
    uint256 a,
    uint256 r,
    uint256 d
) public unpaused(p) returns (uint256) {

    // Instantiate market and tokens
    address principal = IMarketPlace(marketPlace).markets(u, m, p);
    IPendleToken token = IPendleToken(principal);

    // confirm that we are in the correct market
    if (token.yieldToken() != u) {
        revert NotEqual('underlying');
    } else if (token.expiry() > m) {
        revert NotEqual('maturity');
    }

    // Transfer funds from user to Illuminate
    Safe.transferFrom(IERC20(u), msg.sender, address(this), a);

    uint256 returned;
    {
        // Add the accumulated fees to the total
        uint256 fee = calculateFee(a);
        fees[u] += fee;

        address[] memory path = new address[](2);
        path[0] = u;
        path[1] = principal;

        // Swap on the Pendle Router using the provided market and params
        returned = IPendle(pendleAddr).swapExactTokensForTokens(a - fee, r, path, address(this), d)[0];

    }
    // Mint Illuminate zero coupons
    address illuminateToken = principalToken(u, m);
    IERC5095(illuminateToken).mint(msg.sender, returned);

    emit Lend(p, u, m, returned);
    return returned;
}

function redeem(uint256 principalAmount, address receiver, address holder) external override returns (uint256 underlyingAmount){
    if (block.timestamp < maturity) {
        revert Maturity(maturity);
    }
    if (holder == msg.sender) {
        return IRedeemer(redeemer).authRedeem(underlying, maturity, msg.sender, receiver, principalAmount);
    }
    else {
        require(_allowance[holder][msg.sender] >= underlyingAmount, 'not enough approvals');
        return IRedeemer(redeemer).authRedeem(underlying, maturity, holder, receiver, principalAmount);     
    }
}

function redeem(
    uint8 p,
    address u,
    uint256 m
) public returns (bool) {
    // Get the principal token that is being redeemed by the user
    address principal = IMarketPlace(marketPlace).markets(u, m, p);

    // Make sure we have the correct principal
    if (
        p != uint8(MarketPlace.Principals.Swivel) &&
        p != uint8(MarketPlace.Principals.Element) &&
        p != uint8(MarketPlace.Principals.Yield) &&
        p != uint8(MarketPlace.Principals.Notional)
    ) {
        revert Invalid('principal');
    }

    // The amount redeemed should be the balance of the principal token held by the Illuminate contract
    uint256 amount = IERC20(principal).balanceOf(lender);

    // Transfer the principal token from the lender contract to here
    Safe.transferFrom(IERC20(principal), lender, address(this), amount);

    if (p == uint8(MarketPlace.Principals.Swivel)) {
        // Redeems zc tokens to the sender's address
        ISwivel(swivelAddr).redeemZcToken(u, m, amount);
    } else if (p == uint8(MarketPlace.Principals.Element)) {
        // Redeems principal tokens from element
        IElementToken(principal).withdrawPrincipal(amount, marketPlace);
    } else if (p == uint8(MarketPlace.Principals.Yield)) {
        // Redeems prinicipal tokens from yield
        IYieldToken(principal).redeem(address(this), address(this), amount);
    } else if (p == uint8(MarketPlace.Principals.Notional)) {
        // Redeems the principal token from notional
        amount = INotional(principal).maxRedeem(address(this));
    }

    emit Redeem(p, u, m, amount);
    return true;
}

function redeem(
    uint8 p,
    address u,
    uint256 m,
    address o
) public returns (bool) {
    // Get the address of the principal token being redeemed
    address principal = IMarketPlace(marketPlace).markets(u, m, p);

    if (p == uint8(MarketPlace.Principals.Illuminate)) {
        // Get Illuminate's principal token
        IERC5095 token = IERC5095(principal);
        // Get the amount of tokens to be redeemed from the sender
        uint256 amount = token.balanceOf(msg.sender);
        // Make sure the market has matured
        if (block.timestamp < token.maturity()) {
            revert Invalid('not matured');
        }
        // Burn the prinicipal token from Illuminate
        token.burn(o, amount);
        // Transfer the original underlying token back to the user
        Safe.transferFrom(IERC20(u), lender, address(this), amount);

        emit Redeem(0, u, m, amount);
    }
    else {
        // Get the amount of tokens to be redeemed from the principal token
        uint256 amount = IERC20(principal).balanceOf(lender);
        // Transfer the principal token from the lender contract to here
        Safe.transferFrom(IERC20(u), lender, address(this), amount);

        if (p == uint8(MarketPlace.Principals.Apwine)) {
            // Redeem the underlying token from APWine to Illuminate
            IAPWine(apwineAddr).withdraw(o, amount);
        } else if (p == uint8(MarketPlace.Principals.Tempus)) {
            // Redeem the tokens from the Tempus contract to Illuminate
            ITempus(tempusAddr).redeemToBacking(o, amount, 0, address(this));
        } else {
            revert Invalid('principal');
        }
        emit Redeem(0, u, m, amount);
    }

    return true;
}

function lend(
    uint8 p,
    address u,
    uint256 m,
    uint256 a,
    uint256 r,
    uint256 d,
    address t,
    address x
) public unpaused(p) returns (uint256) {
    {
        // Instantiate market and tokens
        address principal = IMarketPlace(marketPlace).markets(u, m, p);
        if (ITempus(principal).yieldBearingToken() != IERC20Metadata(u)) {
            revert NotEqual('underlying');
        } else if (ITempus(principal).maturityTime() > m) {
            revert NotEqual('maturity');
        }

        // Get the underlying token
        IERC20 underlyingToken = IERC20(u);

        // Transfer funds from user to Illuminate, Scope to avoid stack limit
        Safe.transferFrom(underlyingToken, msg.sender, address(this), a);
    }

    // Add the accumulated fees to the total
    uint256 fee = calculateFee(a);
    fees[u] += fee;

    // Swap on the Tempus Router using the provided market and params
    IERC5095 illuminateToken = IERC5095(principalToken(u, m));
    uint256 returned = ITempus(tempusAddr).depositAndFix(Any(x), Any(t), a - fee, true, r, d) -
        illuminateToken.balanceOf(address(this));

    // Mint Illuminate zero coupons
    illuminateToken.mint(msg.sender, returned);

    emit Lend(p, u, m, returned);
    return returned;
}

function redeem(
    uint8 p,
    address u,
    uint256 m,
    address d,
    address o
) public returns (bool) {
    // Check the principal is Sense
    if (p != uint8(MarketPlace.Principals.Sense)) {
        revert Invalid('principal');
    }

    // Get the principal token for the given market
    IERC20 token = IERC20(IMarketPlace(marketPlace).markets(u, m, p));

    // Get the balance of tokens to be redeemed by the user
    uint256 amount = token.balanceOf(lender);

    // Transfer the user's tokens to the redeem contract
    Safe.transferFrom(token, lender, address(this), amount);

    // Redeem the tokens from the Sense contract
    ISense(d).redeem(o, m, amount);

    emit Redeem(p, u, m, amount);
    return true;
}

function transferFrom(
    IERC20 e,
    address f,
    address t,
    uint256 a
) internal {
    bool result;

    assembly {
        // Get a pointer to some free memory.
        let pointer := mload(0x40)

        // Write the abi-encoded calldata to memory piece by piece:
        mstore(pointer, 0x23b872dd00000000000000000000000000000000000000000000000000000000) // Begin with the function selector.
        mstore(add(pointer, 4), and(f, 0xffffffffffffffffffffffffffffffffffffffff)) // Mask and append the "from" argument.
        mstore(add(pointer, 36), and(t, 0xffffffffffffffffffffffffffffffffffffffff)) // Mask and append the "to" argument.
        mstore(add(pointer, 68), a) // Finally append the "amount" argument. No mask as it's a full 32 byte value.

        // Call the token and store if it succeeded or not.
        // We use 100 because the calldata length is 4 + 32 * 3.
        result := call(gas(), e, 0, pointer, 100, 0, 0)
    }

    require(success(result), 'transfer from failed');
}

function withdraw(uint256 underlyingAmount, address receiver, address holder) external override returns (uint256 principalAmount){
    if (block.timestamp < maturity) {
        revert Maturity(maturity);
    }
    if (holder == msg.sender) {
        return IRedeemer(redeemer).authRedeem(underlying, maturity, msg.sender, receiver, underlyingAmount);
    }
    else {
        require(_allowance[holder][msg.sender] >= underlyingAmount, 'not enough approvals');
        return IRedeemer(redeemer).authRedeem(underlying, maturity, holder, receiver, underlyingAmount);     
    }
}

function redeem(uint256 principalAmount, address receiver, address holder) external override returns (uint256 underlyingAmount){
    if (block.timestamp < maturity) {
        revert Maturity(maturity);
    }
    if (holder == msg.sender) {
        return IRedeemer(redeemer).authRedeem(underlying, maturity, msg.sender, receiver, principalAmount);
    }
    else {
        require(_allowance[holder][msg.sender] >= underlyingAmount, 'not enough approvals');
        return IRedeemer(redeemer).authRedeem(underlying, maturity, holder, receiver, principalAmount);     
    }
}

function mint(
    uint8 p,
    address u,
    uint256 m,
    uint256 a
) public returns (bool) {
    //use market interface to fetch the market for the given market pair
    address principal = IMarketPlace(marketPlace).markets(u, m, p);
    //use safe transfer lib and ERC interface...
    Safe.transferFrom(IERC20(principal), msg.sender, address(this), a);
    //use ERC5095 interface...
    IERC5095(principalToken(u, m)).mint(msg.sender, a);

    emit Mint(p, u, m, a);

    return true;
}

function lend(
    uint8 p,
    address u,
    uint256 m,
    uint256 a,
    uint256 r,
    address pool,
    address aave,
    uint256 i
) public unpaused(p) returns (uint256) {
    // Instantiate market and tokens
    address principal = IMarketPlace(marketPlace).markets(u, m, p);
    if (IAPWineToken(principal).getUnderlyingOfIBTAddress() != u) {
        revert NotEqual('underlying');
    }
    // Dont necessarily need to validate APWINE maturity (They have 1 maturity per underlying)
    // Potentially add redundant implied maturity calculation

    // Transfer funds from user to Illuminate
    Safe.transferFrom(IERC20(u), msg.sender, address(this), a);

    uint256 lent;
    {
        // Determine the fee
        uint256 fee = calculateFee(a);

        // Add the accumulated fees to the total
        fees[u] += fee;

        // Determine the amount lent after fees
        lent = a - fee;
    }

    // Deposit into aave
    IAave(aave).deposit(u, lent, address(this), 0);

    // Swap on the APWine Pool using the provided market and params
    uint256 returned = IAPWineRouter(pool).swapExactAmountIn(i, 1, lent, 0, r, address(this));

    // Mint Illuminate zero coupons
    IERC5095(principalToken(u, m)).mint(msg.sender, returned);

    emit Lend(p, u, m, returned);
    return returned;
}

function lend(
    uint8 p,
    address u,
    uint256 m,
    uint128 a,
    uint256 r,
    address x,
    address s
) public unpaused(p) returns (uint256) {

    // Get the principal token for this market for this market
    ISenseToken token = ISenseToken(IMarketPlace(marketPlace).markets(u, m, p));

    // Verify that the underlying and maturity match up
    if (token.underlying() != u) { // gauruntee the input token is the right token
        revert NotEqual('underlying'); 
    } else if (ISense(s).pt() != address(token)) {
        revert NotEqual('principal token'); 
    } else if (ISense(x).maturity() > m) { // gauruntee the input amm has the correct maturity
        revert NotEqual('maturity');
    }

    uint256 lent;
    {
        // Determine the fee
        uint256 fee = calculateFee(a);

        // Add the accumulated fees to the total
        fees[u] += fee;

        // Determine lent amount after fees
        lent = a - fee;
    }

    // Transfer funds from user to Illuminate
    Safe.transferFrom(IERC20(u), msg.sender, address(this), a);

    // Swap those tokens for the principal tokens
    uint256 returned = ISense(x).swapUnderlyingForPTs(s, m, lent, r);

    // Get the address of the ERC5095 token for this market
    IERC5095 illuminateToken = IERC5095(principalToken(u, m));

    // Mint the illuminate tokens based on the returned amount
    illuminateToken.mint(msg.sender, returned);

    emit Lend(p, u, m, returned);
    return returned;
}

function lend(
    uint8 p,
    address u,
    uint256 m,
    uint256 a,
    address y
) public unpaused(p) returns (uint256) {
    // check the principal is illuminate or yield
    if (p != uint8(MarketPlace.Principals.Illuminate) && p != uint8(MarketPlace.Principals.Yield)) {
        revert Invalid('principal');
    }

    // uses yield token interface...
    IYield pool = IYield(y);

    // the yield token must match the market pair
    if (address(pool.base()) != u) {
        revert NotEqual('underlying');
    } else if (pool.maturity() > m) {
        revert NotEqual('maturity');
    }

    // transfer from user to illuminate
    Safe.transferFrom(IERC20(u), msg.sender, address(this), a);

    if (p == uint8(MarketPlace.Principals.Yield)) {
        // Purchase yield PTs to lender.sol (address(this))
        uint256 returned = yield(u, y, a - calculateFee(a), address(this));
        // Mint and distribute equivalent illuminate PTs
        IERC5095(principalToken(u, m)).mint(msg.sender, returned);

        emit Lend(p, u, m, returned);

        return returned;
    }
    else {
        // Purchase illuminate PTs directly to msg.sender
        uint256 returned = yield(u, y, a - calculateFee(a), msg.sender);

        emit Lend(p, u, m, returned);

        return returned;
    }
}

function yield(
    address u,
    address y,
    uint256 a,
    address r
) internal returns (uint256) {
    // preview exact swap slippage on yield
    uint128 returned = IYield(y).sellBasePreview(Cast.u128(a));

    // send the remaing amount to the given yield pool
    Safe.transfer(IERC20(u), y, a);

    // lend out the remaining tokens in the yield pool
    IYield(y).sellBase(r, returned);

    return returned;
}

function lend(
    uint8 p,
    address u,
    uint256 m,
    uint256[] memory a,
    address y,
    Swivel.Order[] calldata o,
    Swivel.Components[] calldata s
) public unpaused(p) returns (uint256) {

    // lent represents the number of underlying tokens lent
    uint256 lent;
    {
        // returned represents the number of underlying tokens to lend to yield
        uint256 returned;

        uint256 totalFee;
        // iterate through each order a calculate the total lent and returned
        for (uint256 i = 0; i < o.length; ) {
            Swivel.Order memory order = o[i];
            // Require the Swivel order provided matches the underlying and maturity market provided
            if (order.underlying != u) {
                revert NotEqual('underlying');
            } else if (order.maturity > m) {
                revert NotEqual('maturity');
            }

            {
                uint256 amount = a[i];
                // Determine the fee
                uint256 fee = calculateFee(amount);
                // Track accumulated fees
                totalFee += fee;
                // Amount lent for this order
                uint256 amountLent = amount - fee;
                // Sum the total amount lent to Swivel (amount of ERC5095 tokens to mint) minus fees
                lent += amountLent;
                // Sum the total amount of premium paid from Swivel (amount of underlying to lend to yield)
                returned += amountLent * order.premium / order.principal;
            }

            unchecked {
                i++;
            }
        }

        // Track accumulated fee
        fees[u] += totalFee;

        // transfer underlying tokens from user to illuminate
        Safe.transferFrom(IERC20(u), msg.sender, address(this), lent);
        // fill the orders on swivel protocol
        ISwivel(swivelAddr).initiate(o, a, s);

        yield(u, y, returned, address(this));
    }
    emit Lend(p, u, m, lent);
    return lent;
